trigger CaseTrigger on Case (after update) {
    if (Trigger.isAfter && Trigger.isUpdate) {
        Set<Id> caseIds = new Set<Id>();

        for (Case c : Trigger.new) {
            Case oldCase = Trigger.oldMap.get(c.Id);

            // Fire only on the transition from "not closed" -> "closed"
            Boolean justClosed = c.IsClosed && !oldCase.IsClosed;

            // Only cases that actually have a contact need a survey task.
            if (justClosed && c.ContactId != null) {
                caseIds.add(c.Id);
            }
        }

        if (!caseIds.isEmpty()) {
            // Enqueue a single job for the whole batch. Salesforce only allows
            // 50 System.enqueueJob calls per transaction, so a per-case enqueue
            // breaks the nightly "close up to 200 at a time" path. Instead we
            // hand the job the full set of Ids and isolate failures inside the
            // job (try/catch per case) so one bad case can't affect the others.
            System.enqueueJob(new CaseSurveyJob(caseIds));
        }
    }
}
