public with sharing class EmployeeDirectoryService {
    public static List<FB_Employee__c> getDirectory() {
        // If the running user cannot read the object at all, return empty list.
        if (!Schema.sObjectType.FB_Employee__c.isAccessible()) {
            return new List<FB_Employee__c>();
        }

        Map<String, Schema.SObjectField> fieldMap =
            Schema.SObjectType.FB_Employee__c.fields.getMap();

        // Always-selectable fields (Id and Name are needed for ordering/identity).
        List<String> fieldsToQuery = new List<String>{ 'Id', 'Name' };

        // Only add the custom fields the running user can actually read, so the
        // query does not fail and inaccessible fields are simply never selected.
        for (String fieldName : new List<String>{
                'Department__c', 'Salary__c', 'Personal_Email__c' }) {
            Schema.SObjectField field = fieldMap.get(fieldName.toLowerCase());
            if (field != null && field.getDescribe().isAccessible()) {
                fieldsToQuery.add(fieldName);
            }
        }

        String soql =
            'SELECT ' + String.join(fieldsToQuery, ', ') +
            ' FROM FB_Employee__c ORDER BY Name ASC';

        // Runs "with sharing", so only records visible through sharing are returned.
        List<FB_Employee__c> records = Database.query(soql);

        // Defensive strip to ensure no inaccessible field is present on the records.
        SObjectAccessDecision decision = Security.stripInaccessible(
            AccessType.READABLE,
            records
        );

        return (List<FB_Employee__c>) decision.getRecords();
    }
}
