public with sharing class TA_Contact_PreventDuplicateEmail
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        process((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldMap = new Map<Id, Contact>();
        for (SObject so : triggerOld) {
            Contact c = (Contact) so;
            oldMap.put(c.Id, c);
        }
        process((List<Contact>) triggerNew, oldMap);
    }

    private void process(List<Contact> newList, Map<Id, Contact> oldMap) {
        // Determine which contacts actually need checking.
        List<Contact> toCheck = new List<Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<Id> recordIds = new Set<Id>();

        for (Contact c : newList) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact oldC = oldMap.get(c.Id);
                Boolean emailChanged = (oldC == null) || (c.Email != oldC.Email);
                Boolean accountChanged = (oldC == null) || (c.AccountId != oldC.AccountId);
                if (!emailChanged && !accountChanged) {
                    continue;
                }
            }
            toCheck.add(c);
            accountIds.add(c.AccountId);
            if (c.Id != null) {
                recordIds.add(c.Id);
            }
        }

        if (toCheck.isEmpty()) {
            return;
        }

        // One SOQL query: existing account+email combinations in the database.
        Set<String> existingKeys = new Set<String>();
        for (Contact c : [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
        ]) {
            if (recordIds.contains(c.Id)) {
                continue; // a contact never conflicts with itself
            }
            existingKeys.add(buildKey(c.AccountId, c.Email));
        }

        // Iterate in list order: first wins, each later duplicate is rejected.
        Set<String> batchSeen = new Set<String>();
        for (Contact c : toCheck) {
            String key = buildKey(c.AccountId, c.Email);
            if (existingKeys.contains(key) || batchSeen.contains(key)) {
                c.addError(ERROR_MESSAGE);
            } else {
                batchSeen.add(key);
            }
        }
    }

    private String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.trim().toLowerCase();
    }
}
