```apex
/**
 * Singleton that holds shared query results for Contact trigger actions, so that
 * the parent Accounts are queried exactly once per trigger execution and reused
 * by every action that needs them.
 */
public inherited sharing class TA_Contact_Queries {
    private static TA_Contact_Queries instance;

    /**
     * Parent accounts of the contacts in the current trigger context, keyed by Id.
     * Populated by the Service trigger action which runs first in before insert.
     */
    public Map<Id, Account> accountsById = new Map<Id, Account>();

    private TA_Contact_Queries() {
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action which loads the parent Account map. It is registered to run
     * first (Order 1) in before insert and reloads the map on every trigger
     * execution, because later DML in the same transaction can involve other
     * accounts.
     */
    public inherited sharing class Service implements TriggerAction.BeforeInsert {
        public void beforeInsert(List<SObject> triggerNew) {
            Set<Id> accountIds = new Set<Id>();
            for (SObject record : triggerNew) {
                Contact con = (Contact) record;
                if (con.AccountId != null) {
                    accountIds.add(con.AccountId);
                }
            }

            Map<Id, Account> loadedAccounts = new Map<Id, Account>();
            if (!accountIds.isEmpty()) {
                loadedAccounts = new Map<Id, Account>(
                    [
                        SELECT
                            Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                        FROM Account
                        WHERE Id IN :accountIds
                    ]
                );
            }

            TA_Contact_Queries.getInstance().accountsById = loadedAccounts;
        }
    }
}
